package com.campusradar.notification;

import com.campusradar.common.*;
import org.springframework.stereotype.Service;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import static com.campusradar.common.SqlRows.map;

@Service
public class NotificationService {
    public final SqlRows sql;private final SubscriptionMail mail;
    public NotificationService(SqlRows sql,SubscriptionMail mail){this.sql=sql;this.mail=mail;}
    public static final String BASE="id,version,created_at,updated_at";
    public static final String SUB=BASE+",name,conditions,in_app,email_enabled AS email,enabled";
    public static final String NOTICE=BASE+",type,title,body,target_path,read_at";
    public static final String HIT=BASE+",subscription_id,job_id,job_version,notification_id";
    private static ApiProblem missing(){return new ApiProblem(404,"NOT_FOUND","记录不存在或不可访问。");}
    public static void page(int page,int size){if(page<1||page>500||size<1||size>100)throw new ApiProblem(422,"VALIDATION_ERROR","分页参数无效。");}
    public static void version(Map<String,Object> row,int expected){if(((Number)row.get("version")).intValue()!=expected)throw new ApiProblem(409,"VERSION_CONFLICT","记录已更新，请刷新后重试。");}
    public Map<String,Object> one(String user,String id){return sql.one("SELECT "+SUB+" FROM subscriptions WHERE user_id=:u AND id=:id",map("u",user,"id",id),Set.of("conditions"),Set.of("in_app","email","enabled"));}
    private void delivery(String user,Map<String,Object>b){if(!Boolean.TRUE.equals(b.get("inApp"))&&!Boolean.TRUE.equals(b.get("email")))throw new ApiProblem(422,"VALIDATION_ERROR","请至少选择一种通知渠道。");if(Boolean.TRUE.equals(b.get("email"))&&Boolean.TRUE.equals(b.get("enabled"))){mail.ensureConfigured();if(sql.db.queryForObject("SELECT COUNT(*) FROM users WHERE id=:u AND status='ACTIVE'",map("u",user),Integer.class)==0)throw new ApiProblem(403,"ACCOUNT_INACTIVE","账号当前不可用。");}}
    public Map<String,Object> create(String user,Map<String,Object>b){delivery(user,b);String id=UUID.randomUUID().toString();sql.db.update("INSERT INTO subscriptions(id,user_id,name,conditions,in_app,email_enabled,enabled) VALUES(:id,:u,:name,:conditions,:inApp,:email,:enabled)",map("id",id,"u",user,"name",b.get("name"),"conditions",sql.json.writeValueAsString(b.get("conditions")),"inApp",b.get("inApp"),"email",b.get("email"),"enabled",b.get("enabled")));return one(user,id);}
    public Map<String,Object> patch(String user,String id,Map<String,Object>b){var full=new LinkedHashMap<>(one(user,id));version(full,((Number)b.get("version")).intValue());full.putAll(b);delivery(user,full);sql.db.update("UPDATE subscriptions SET name=:name,conditions=:conditions,in_app=:inApp,email_enabled=:email,enabled=:enabled,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE user_id=:u AND id=:id",map("id",id,"u",user,"name",full.get("name"),"conditions",sql.json.writeValueAsString(full.get("conditions")),"inApp",full.get("inApp"),"email",full.get("email"),"enabled",full.get("enabled")));return one(user,id);}
    public Object delete(String user,String id,int expected){version(one(user,id),expected);var p=map("id",id,"u",user);sql.db.update("DELETE FROM subscription_hits WHERE user_id=:u AND subscription_id=:id",p);sql.db.update("DELETE FROM subscriptions WHERE user_id=:u AND id=:id",p);return null;}
    public Map<String,Object> notification(String user,String id){return sql.one("SELECT "+NOTICE+" FROM notifications WHERE user_id=:u AND id=:id",map("u",user,"id",id),Set.of(),Set.of());}
    public Map<String,Object> notificationPatch(String user,String id,int expected,boolean read){version(notification(user,id),expected);sql.db.update("UPDATE notifications SET read_at=:read,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE user_id=:u AND id=:id",map("u",user,"id",id,"read",read?Timestamp.from(Instant.now()):null));return notification(user,id);}
    public Object notificationDelete(String user,String id,int expected){version(notification(user,id),expected);var p=map("u",user,"id",id);sql.db.update("UPDATE subscription_hits SET notification_id=NULL,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE user_id=:u AND notification_id=:id",p);sql.db.update("DELETE FROM notifications WHERE user_id=:u AND id=:id",p);return null;}
    public Object readAll(String user,Instant cutoff){sql.db.update("UPDATE notifications SET read_at=:cutoff,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE user_id=:u AND read_at IS NULL AND created_at<=:cutoff",map("u",user,"cutoff",Timestamp.from(cutoff)));return map("accepted",true);}
    @SuppressWarnings("unchecked") public Object scan(String user,String id){var sub=one(user,id);if(!Boolean.TRUE.equals(sub.get("enabled")))return map("matched",0,"created",0);var conditions=(Map<String,Object>)sub.get("conditions");var p=map("u",user,"sub",id);var where=new StringBuilder(" FROM jobs j JOIN sources s ON s.id=j.source_id WHERE s.enabled=1 AND j.publication_status='PUBLISHED' AND j.status='OPEN'");for(String field:List.of("roles","cities","recruitmentTypes")){var values=(List<?>)conditions.get(field);if(!values.isEmpty()){p.put(field,values);where.append(switch(field){case "roles"->" AND j.role IN (:roles)";case "cities"->" AND EXISTS(SELECT 1 FROM job_cities c WHERE c.job_id=j.id AND c.city IN (:cities))";default->" AND j.recruitment_type IN (:recruitmentTypes)";});}}if(conditions.get("graduationYear")!=null){p.put("year",conditions.get("graduationYear"));where.append(" AND EXISTS(SELECT 1 FROM job_graduation_years y WHERE y.job_id=j.id AND y.graduation_year=:year)");}var jobs=sql.query("SELECT j.id,j.title,j.version"+where+" ORDER BY j.id",p);int created=0;String email=null;if(Boolean.TRUE.equals(sub.get("email"))){delivery(user,sub);email=sql.db.queryForObject("SELECT email FROM users WHERE id=:u",p,String.class);}for(var job:jobs){p.put("job",job.get("id"));p.put("version",job.get("version"));if(sql.db.queryForObject("SELECT COUNT(*) FROM subscription_hits WHERE user_id=:u AND subscription_id=:sub AND job_id=:job AND job_version=:version",p,Integer.class)>0)continue;String dedup="subscription:"+id+":"+job.get("id")+":"+job.get("version");String notification=null;if(Boolean.TRUE.equals(sub.get("inApp"))){notification=UUID.randomUUID().toString();sql.db.update("INSERT INTO notifications(id,user_id,type,title,body,target_path,dedup_key) VALUES(:id,:u,'JOB_HIT',:title,:body,:path,:dedup)",map("id",notification,"u",user,"title",("订阅命中 · "+job.get("title")).substring(0,Math.min(200,("订阅命中 · "+job.get("title")).length())),"body","你的订阅「"+sub.get("name")+"」匹配到新的岗位版本。","path","/jobs/"+job.get("id"),"dedup",dedup));}if(email!=null)mail.queue(user,email,dedup,"订阅命中 · "+job.get("title"),"你的订阅「"+sub.get("name")+"」匹配到岗位："+job.get("title"),"/jobs/"+job.get("id"));sql.db.update("INSERT INTO subscription_hits(id,user_id,subscription_id,job_id,job_version,notification_id) VALUES(:id,:u,:sub,:job,:version,:notice)",map("id",UUID.randomUUID().toString(),"u",user,"sub",id,"job",job.get("id"),"version",job.get("version"),"notice",notification));created++;}sql.db.update("UPDATE subscriptions SET last_scanned_at=CURRENT_TIMESTAMP WHERE id=:sub AND user_id=:u",p);if(created>0)sql.db.update("UPDATE users SET data_revision=data_revision+1 WHERE id=:u",p);return map("matched",jobs.size(),"created",created);}
}
